204	/// The type of prompt.
205	#[derive(Debug, Clone)]
206	pub enum PromptType {
207	    /// Yes/no confirmation.
208	    Confirm,
209	    /// Free-form text input.
210	    Input,
211	    /// Select one from a list of options.
212	    Select { options: Vec<PromptOption> },
213	    /// Select multiple from a list of options.
214	    MultiSelect { options: Vec<PromptOption> },
215	}
