//! Feedback command implementation.
//!
//! Captures and manages friction points during dogfooding, with automatic
//! session correlation and optional external delivery via GitHub issues
//! or email.

use anyhow::Result;
use clap::{Args, Subcommand};

use crate::feedback::delivery::{
    self, build_github_url, build_mailto_url, build_preview, build_title, DeliveryMethod,
};
use crate::feedback::{default_store_path, FeedbackEntry, FeedbackStatus, FeedbackStore};
use crate::session::{default_store_path as session_store_path, Session, SessionId, SessionStore};
use crate::ui::{Prompt, PromptOption, PromptResult, PromptType, UserInterface};

use super::dispatcher::{Command, CommandResult};

/// Known feedback categories that map to delivery routing.
const KNOWN_CATEGORIES: &[&str] = &["bug", "feature", "ux", "other"];

/// Arguments for the `feedback` command.
#[derive(Debug, Clone, Args)]
pub struct FeedbackArgs {
    #[command(subcommand)]
    pub command: Option<FeedbackSubcommand>,

    /// Feedback message (when not using a subcommand).
    pub message: Vec<String>,

    /// Tags for categorization.
    #[arg(short, long, value_delimiter = ',')]
    pub tag: Vec<String>,

    /// Session ID to attach (defaults to most recent).
    #[arg(long)]
    pub session: Option<String>,

    /// Skip the delivery prompt (save locally only).
    #[arg(long)]
    pub no_deliver: bool,
}

/// Feedback subcommands.
#[derive(Debug, Clone, Subcommand)]
pub enum FeedbackSubcommand {
    /// List feedback entries.
    List {
        /// Filter by status (open, resolved, wontfix).
        #[arg(long)]

content.content:
200	                    value: "bug".to_string(),
201	                },
202	                PromptOption {
203	                    label: "UX - confusing or awkward".to_string(),
204	                    value: "ux".to_string(),
205	                },
206	                PromptOption {
207	                    label: "Feature - missing or incomplete".to_string(),
208	                    value: "feature".to_string(),
209	                },
210	                PromptOption {
211	                    label: "Other".to_string(),
212	                    value: "other".to_string(),
213	                },
214	            ],
215	        },
216	        default: None,
217	    };
218	
219	    let category = match ui.prompt(&category_prompt)? {
220	        PromptResult::String(s) => s,
221	        _ => "other".to_string(),
222	    };
223	
224	    let prompt = Prompt {
225	        key: "feedback_message".to_string(),
226	        question: "Describe your feedback:".to_string(),
227	        prompt_type: PromptType::Input,
228	        default: None,
229	    };
230	
231	    let result = ui.prompt(&prompt)?;
232	    let message = match result {
233	        PromptResult::String(s) => s,
234	        _ => String::new(),
235	    };
236	
237	    if message.is_empty() {
238	        ui.warning("No feedback provided");
239	        return Ok(1);
240	    }
241	
242	    // Merge category into tags
243	    let mut all_tags = tags;
244	    if !category.is_empty() && category != "other" {
245	        all_tags.insert(0, category.clone());
246	    }
247	
248	    let all_tags = if all_tags.is_empty() {
249	        let tag_prompt = Prompt {
250	            key: "feedback_tags".to_string(),
251	            question: "Tags (optional, comma-separated):".to_string(),
252	            prompt_type: PromptType::Input,
253	            default: None,
254	        };
255	
256	        match ui.prompt(&tag_prompt)? {
257	            PromptResult::String(s) if !s.is_empty() => {
258	                s.split(',').map(|s| s.trim().to_string()).collect()
259	            }
260	            _ => vec![],
261	        }
262	    } else {
263	        all_tags
264	    };
265	
266	    capture_feedback(store, &message, &category, all_tags, None, no_deliver, ui)
267	}
