269	/// Offer to deliver feedback externally via GitHub issue or email.
270	fn offer_delivery(
271	    store: &FeedbackStore,
272	    entry: &FeedbackEntry,
273	    category: &str,
274	    session: Option<&Session>,
275	    ui: &mut dyn UserInterface,
276	) -> Result<()> {
277	    let method = delivery::determine_method(category);
278	
279	    // Show preview
280	    let preview = build_preview(entry, category, session, &method);
281	    ui.message(&preview);
282	
283	    // Prompt for confirmation
284	    let confirm_prompt = Prompt {
285	        key: "feedback_deliver".to_string(),
286	        question: "Send feedback?".to_string(),
287	        prompt_type: PromptType::Select {
288	            options: vec![
289	                PromptOption {
290	                    label: "Open in browser".to_string(),
291	                    value: "yes".to_string(),
292	                },
293	                PromptOption {
294	                    label: "Skip".to_string(),
295	                    value: "no".to_string(),
296	                },
297	            ],
298	        },
299	        default: None,
300	    };
301	
302	    let response = ui.prompt(&confirm_prompt)?;
303	    let choice = match response {
304	        PromptResult::String(s) => s,
305	        _ => "no".to_string(),
306	    };
307	
308	    if choice == "yes" {
309	        let url = match &method {
310	            DeliveryMethod::GitHubIssue { labels } => {
311	                let title = build_title(entry, category);
312	                let body = delivery::scrub_payload(&delivery::build_github_body(entry, session));
