154	fn poll_fd(fd: RawFd, timeout: i32) -> io::Result<bool> {
155	    let mut pollfd = libc::pollfd {
156	        fd,
157	        events: libc::POLLIN,
158	        revents: 0,
159	    };
160	    let ret = unsafe { libc::poll(&mut pollfd as *mut _, 1, timeout) };
161	    if ret < 0 {
