403	fn make_raw(termios: &mut libc::termios) {
404	    // This is the manual implementation for QNX, which does not have cfmakeraw.
405	    termios.c_iflag &= !(libc::IGNBRK
406	        | libc::BRKINT
407	        | libc::PARMRK
408	        | libc::ISTRIP
409	        | libc::INLCR
410	        | libc::IGNCR
411	        | libc::ICRNL
412	        | libc::IXON);
413	    termios.c_oflag &= !libc::OPOST;
414	    termios.c_lflag &= !(libc::ECHO | libc::ECHONL | libc::ICANON | libc::ISIG | libc::IEXTEN);
415	    termios.c_cflag &= !(libc::CSIZE | libc::PARENB);
416	    termios.c_cflag |= libc::CS8;
417	}
